// Format invoice data according to European Standard EN 16931 (ZUGFeRD 2.2 / Factur-X)
const item = $input.item.json;
const now = new Date();
const todayStr = now.toISOString().split('T')[0];

const customerEmail = item.customer_details?.email || item.buyer_email || 'user@example.com';
const customerName = item.customer_details?.name || item.buyer_name || 'Max Mustermann';
const invoiceNum = item.invoice_number || 'INV-' + now.getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);

const lineItems = item.line_items || [
  {
    description: item.description || 'Digitale Dienstleistung / Softwarelizenz',
    quantity: '1.0',
    unit_price: item.amount_total ? (item.amount_total / 100 / 1.19).toFixed(2) : '100.00',
    tax_rate_percent: '19.0'
  }
];

const invoicePayload = {
  invoice_number: invoiceNum,
  issue_date: todayStr,
  currency: 'EUR',
  seller: {
    name: 'Meine Firma GmbH',
    street: 'Musterstraße 10',
    city: 'Frankfurt am Main',
    zip_code: '60311',
    country: 'DE',
    vat_id: 'DE123456789',
    iban: 'DE893704+1234567890'
  },
  buyer: {
    name: customerName,
    street: item.customer_details?.address?.line1 || 'Kundenweg 5',
    city: item.customer_details?.address?.city || 'Berlin',
    zip_code: item.customer_details?.address?.postal_code || '10115',
    country: item.customer_details?.address?.country || 'DE'
  },
  line_items: lineItems
};

return {
  buyer_email: customerEmail,
  buyer_name: customerName,
  invoice_number: invoiceNum,
  invoice_payload: invoicePayload
};
